const both=['₩5,000','1,234','(500)','50%','12.5%','$1,234.50','1,234원','£5,000','(1,234)','₩1,000.50',
  // 예전에는 여기서부터가 두 길에서 갈렸다. 정리는 숫자로 바꾸고 붙여넣기는
  // 글자로 두거나, 그 반대였다.
